pub fn squash(v: &mut Vec<String>) {
    // Remove consecutive duplicates (keep first of each run), comparing the
    // original, un-trimmed values.
    v.dedup();

    // Then trim ASCII whitespace (U+0009..=U+000D and U+0020) from both ends
    // of every surviving string.
    let mut i = 0;
    while i < v.len() {
        let s = v[i].clone();
        let b = s.as_bytes();
        let mut start = 0;
        let mut end = b.len();
        let is_ws = |c: u8| (0x09..=0x0D).contains(&c) || c == b' ';
        while start < end && is_ws(b[start]) {
            start += 1;
        }
        while end > start && is_ws(b[end - 1]) {
            end -= 1;
        }
        // start/end land on char boundaries (trimmed chars are single-byte
        // ASCII), so this slice is always valid UTF-8.
        v[i] = s[start..end].to_string();
        i += 1;
    }
}
