use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

/// A generic least-recently-used cache.
pub struct Lru<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    /// Access order: front = most recently used, back = least recently used.
    order: VecDeque<K>,
}

impl<K, V> Lru<K, V>
where
    K: Eq + Hash + Clone,
{
    /// Creates an empty cache with the given capacity (must be >= 1).
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "Lru capacity must be >= 1");
        Lru {
            cap,
            map: HashMap::new(),
            order: VecDeque::new(),
        }
    }

    /// Inserts or updates a key. Marks it most-recently-used.
    /// If the key is new and the cache is full, evicts the LRU entry.
    pub fn put(&mut self, k: K, v: V) {
        if self.map.contains_key(&k) {
            self.map.insert(k.clone(), v);
            self.order.retain(|x| *x != k);
            self.order.push_front(k);
            return;
        }
        if self.map.len() >= self.cap {
            if let Some(lru_key) = self.order.pop_back() {
                self.map.remove(&lru_key);
            }
        }
        self.map.insert(k, v);
        self.order.push_front(k);
    }

    /// Returns the value for `k`, marking the entry as most-recently-used.
    pub fn get(&mut self, k: &K) -> Option<&V> {
        if !self.map.contains_key(k) {
            return None;
        }
        self.order.retain(|x| x != k);
        self.order.push_front(k.clone());
        self.map.get(k)
    }
}
