use std::sync::Arc;
use std::thread;

pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    let n = items.len();
    let f = Arc::new(f);

    // Split the input into `workers` contiguous chunks (sizes differ by at
    // most 1). Each thread owns its chunk, and since chunks are processed in
    // index order and joined in the same order, results stay in the original
    // input order.
    let base = n / workers;
    let extra = n % workers;

    let mut handles = Vec::with_capacity(workers);
    let mut rest = items;
    for i in 0..workers {
        let len = base + if i < extra { 1 } else { 0 };
        let at = rest.len().saturating_sub(len);
        let chunk = rest.split_off(at);

        let f = Arc::clone(&f);
        handles.push(thread::spawn(move || {
            chunk
                .into_iter()
                .map(|x| f(x))
                .collect::<Vec<R>>()
        }));
    }

    let mut out: Vec<R> = Vec::with_capacity(n);
    for handle in handles {
        out.extend(handle.join().expect("parallel_map worker panicked"));
    }
    out
}
