use std::marker::PhantomData;

/// An iterator over non-overlapping consecutive pairs of a mutable slice.
///
/// Each item is a pair of `&mut` references into the original slice.
/// Every element of the slice is yielded at most once; if the slice has
/// odd length the trailing element is dropped.
pub struct PairsMut<'a, T> {
    ptr: *mut T,
    len: usize,
    pos: usize,
    _marker: PhantomData<&'a mut [T]>,
}

/// Splits a mutable slice into an iterator of non-overlapping consecutive
/// pairs `(first, second)`.
///
/// For `[a, b, c, d, e]` this yields `(a, b)` then `(c, d)`, dropping `e`.
pub fn pairs_mut<T>(s: &mut [T]) -> PairsMut<'_, T> {
    PairsMut {
        ptr: s.as_mut_ptr(),
        len: s.len(),
        pos: 0,
        _marker: PhantomData,
    }
}

impl<'a, T> Iterator for PairsMut<'a, T> {
    type Item = (&'a mut T, &'a mut T);

    fn next(&mut self) -> Option<Self::Item> {
        if self.pos + 2 > self.len {
            return None;
        }
        unsafe {
            // Soundness:
            // - `self.ptr` was derived from the exclusive borrow `&'a mut [T]`,
            //   and `PhantomData<&'a mut [T]>` prevents the iterator from
            //   outliving that borrow.
            // - A pair is only produced when `pos + 2 <= len`, so
            //   `ptr.add(pos)` and `ptr.add(pos + 1)` are always in bounds.
            // - `pos` advances by exactly 2 on every produced pair, so the two
            //   elements within a pair, and all elements across pairs, are
            //   disjoint — no two `&mut T` ever alias.
            let first = self.ptr.add(self.pos);
            let second = self.ptr.add(self.pos + 1);
            self.pos += 2;
            Some((&mut *first, &mut *second))
        }
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let pairs = (self.len - self.pos) / 2;
        (pairs, Some(pairs))
    }
}
