use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread::{self, Thread};

/// A future that yields (returns `Pending`) for `remaining` polls before
/// completing with `()`.
///
/// Every poll while `remaining > 0` decrements the counter, calls
/// `wake_by_ref()` on the context's waker, and returns `Pending`.
/// The first poll with `remaining == 0` resolves to `Ready(())`.
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        if self.remaining > 0 {
            self.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}

/// Shared state between the parked executor thread and the waker.
struct SharedState {
    woken: AtomicBool,
    executor_thread: Thread,
}

/// Waker state for `block_on`. Cloning is just an Arc bump.
#[derive(Clone)]
struct BlockOnWaker(Arc<SharedState>);

impl Wake for BlockOnWaker {
    fn wake(self: Arc<Self>) {
        self.0.woken.store(true, Ordering::Release);
        self.0.executor_thread.unpark();
    }

    fn wake_by_ref(self: &Arc<Self>) {
        self.0.woken.store(true, Ordering::Release);
        self.0.executor_thread.unpark();
    }
}

/// Polls `fut` to completion on the current thread.
///
/// While the future is pending the current thread parks
/// (`thread::park()`). It is re-polled only after the future's waker has
/// been invoked — possibly from another thread — which flips the flag and
/// unparks the executor thread.
pub fn block_on<F: Future>(mut fut: F) -> F::Output {
    let shared = Arc::new(SharedState {
        woken: AtomicBool::new(false),
        executor_thread: thread::current(),
    });
    let waker = Waker::from(Arc::new(BlockOnWaker(shared.clone())));
    let mut cx = Context::from_waker(&waker);

    // Safety: `fut` lives for the whole call, is never moved after the pin
    // is created, and is dropped in place when `block_on` returns.
    let mut fut = unsafe { Pin::new_unchecked(&mut fut) };

    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(output) => return output,
            Poll::Pending => {
                // Wait for a wake. The check-then-park loop guarantees a
                // wake is never lost: a wake sets the flag (Release) and
                // then unparks; if the unpark lands before our `park()`,
                // the park call consumes the pending token and returns
                // immediately, and the loop re-observes the flag.
                loop {
                    if shared.woken.swap(false, Ordering::Acquire) {
                        break;
                    }
                    thread::park();
                }
            }
        }
    }
}
